from pathlib import Path
import sys


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return text.replace(old, new, 1)


def replace_block(text: str, start_marker: str, end_marker: str, replacement: str, label: str) -> str:
    start = text.find(start_marker)
    if start < 0:
        raise RuntimeError(f"{label}: start marker not found")
    end = text.find(end_marker, start)
    if end < 0:
        raise RuntimeError(f"{label}: end marker not found")
    return text[:start] + replacement + text[end:]


def main(path: str) -> None:
    p = Path(path)
    s = p.read_text(encoding="utf-8-sig")

    s = replace_once(s, 'APP_VERSION = "1.11.20"', 'APP_VERSION = "1.11.21"', 'version')

    marker = 'ALLOW_BUNDLED_RULE_BOOTSTRAP = True\n'
    s = replace_once(
        s,
        marker,
        marker + 'DEFAULT_UI_MODE = "modern"\nUI_MODES = {"modern", "classic"}\n',
        'UI mode constants',
    )

    style_marker = '    def _list(self, direction: str) -> List[Transaction]:\n'
    modern_style = '''    def _configure_modern_style(self):\n        s = ttk.Style(self)\n        try:\n            s.theme_use("clam")\n        except tk.TclError:\n            pass\n        self.configure(bg="#f4f7fb")\n        s.configure("Treeview", rowheight=30, font=("Segoe UI", 9), background="#ffffff", fieldbackground="#ffffff", foreground="#253247")\n        s.configure("Treeview.Heading", font=("Segoe UI", 9, "bold"), padding=(7, 8), background="#eef3f8", foreground="#334155")\n        s.configure("Accent.TButton", font=("Segoe UI", 9, "bold"), padding=(10, 7), background="#2563eb", foreground="#ffffff")\n        s.map("Accent.TButton", background=[("active", "#1d4ed8"), ("pressed", "#1e40af")], foreground=[("disabled", "#cbd5e1"), ("!disabled", "#ffffff")])\n        s.configure("Modern.TButton", font=("Segoe UI", 9), padding=(9, 6))\n        s.configure("ModernHeader.TFrame", background="#ffffff")\n        s.configure("ModernPage.TFrame", background="#f4f7fb")\n        s.configure("ModernCard.TFrame", background="#ffffff", relief="solid", borderwidth=1)\n        s.configure("ModernTitle.TLabel", background="#ffffff", foreground="#172033", font=("Segoe UI", 18, "bold"))\n        s.configure("ModernSubtitle.TLabel", background="#ffffff", foreground="#64748b", font=("Segoe UI", 9))\n        s.configure("DashboardTitle.TLabel", background="#f4f7fb", foreground="#172033", font=("Segoe UI", 22, "bold"))\n        s.configure("DashboardText.TLabel", background="#f4f7fb", foreground="#64748b", font=("Segoe UI", 10))\n        s.configure("CardLabel.TLabel", background="#ffffff", foreground="#64748b", font=("Segoe UI", 9))\n        s.configure("CardValue.TLabel", background="#ffffff", foreground="#172033", font=("Segoe UI", 22, "bold"))\n        s.configure("CardNote.TLabel", background="#ffffff", foreground="#64748b", font=("Segoe UI", 8))\n        s.configure("GuideTitle.TLabel", background="#ffffff", foreground="#172033", font=("Segoe UI", 12, "bold"))\n        s.configure("GuideText.TLabel", background="#ffffff", foreground="#475569", font=("Segoe UI", 9))\n        s.configure("StatusBar.TFrame", background="#ffffff")\n\n'''
    s = replace_once(s, style_marker, modern_style + style_marker, 'modern styles')

    new_build = '''    def _build_profile_controls(self, parent, modern: bool = False):\n        box = ttk.Frame(parent, style="ModernHeader.TFrame" if modern else "TFrame")\n        ttk.Label(box, text="Company" if modern else "Company profile:", style="ModernSubtitle.TLabel" if modern else "TLabel").pack(side="left", padx=(0, 6))\n        combo = ttk.Combobox(box, textvariable=self.profile_var, values=self.profile_manager.names(), state="readonly", width=22)\n        combo.pack(side="left")\n        combo.bind("<<ComboboxSelected>>", self.select_profile)\n        ttk.Button(box, text="New", command=self.new_profile, style="Modern.TButton" if modern else "TButton").pack(side="left", padx=(6, 2))\n        ttk.Button(box, text="Rename", command=self.rename_profile, style="Modern.TButton" if modern else "TButton").pack(side="left", padx=2)\n        ttk.Button(box, text="Delete", command=self.delete_profile, style="Modern.TButton" if modern else "TButton").pack(side="left", padx=2)\n        return box, combo\n\n    def _build_dashboard(self):\n        self.dashboard_vars = {}\n        outer = self.dashboard_frame\n        heading = ttk.Frame(outer, style="ModernPage.TFrame", padding=(20, 18, 20, 8))\n        heading.pack(fill="x")\n        ttk.Label(heading, text="Accounting workspace", style="DashboardTitle.TLabel").pack(anchor="w")\n        ttk.Label(heading, text="A guided overview of the current statement and the next action to take.", style="DashboardText.TLabel").pack(anchor="w", pady=(3, 0))\n\n        cards = ttk.Frame(outer, style="ModernPage.TFrame", padding=(20, 8, 20, 8))\n        cards.pack(fill="x")\n        for col in range(5):\n            cards.grid_columnconfigure(col, weight=1, uniform="dashboard_card")\n\n        card_specs = [\n            ("payments", "Payments", "Money out"),\n            ("receipts", "Receipts", "Money in"),\n            ("ready", "Ready", "Selected + allocated"),\n            ("attention", "Needs attention", "Unassigned / ambiguous"),\n            ("rules", "Saved rules", "Automation available"),\n        ]\n        for col, (key, title, note) in enumerate(card_specs):\n            frame = ttk.Frame(cards, style="ModernCard.TFrame", padding=(14, 12))\n            frame.grid(row=0, column=col, sticky="nsew", padx=(0 if col == 0 else 5, 0 if col == 4 else 5))\n            var = tk.StringVar(value="0")\n            self.dashboard_vars[key] = var\n            ttk.Label(frame, text=title, style="CardLabel.TLabel").pack(anchor="w")\n            ttk.Label(frame, textvariable=var, style="CardValue.TLabel").pack(anchor="w", pady=(3, 0))\n            ttk.Label(frame, text=note, style="CardNote.TLabel").pack(anchor="w", pady=(2, 0))\n\n        body = ttk.Frame(outer, style="ModernPage.TFrame", padding=(20, 8, 20, 20))\n        body.pack(fill="both", expand=True)\n        body.grid_columnconfigure(0, weight=3)\n        body.grid_columnconfigure(1, weight=2)\n        body.grid_rowconfigure(0, weight=1)\n\n        guide = ttk.Frame(body, style="ModernCard.TFrame", padding=(18, 16))\n        guide.grid(row=0, column=0, sticky="nsew", padx=(0, 7))\n        ttk.Label(guide, text="Recommended workflow", style="GuideTitle.TLabel").pack(anchor="w")\n        ttk.Label(guide, text="Follow these steps from top to bottom. You can return here at any time.", style="GuideText.TLabel").pack(anchor="w", pady=(2, 10))\n        steps = [\n            ("1", "Load a bank statement", "Choose the CSV exported by your bank."),\n            ("2", "Review allocations", "Resolve orange/unassigned or ambiguous rows. Saved rules can automate future statements."),\n            ("3", "Choose what to export", "Add Auto-Allocated and Manual Allocations; the selections are additive."),\n            ("4", "Validate", "Run the pre-import checks before creating the Pastel files."),\n            ("5", "Export to Pastel", "Import Payments on the Payments side and Receipts on the Receipts side."),\n        ]\n        for number, title, note in steps:\n            row = ttk.Frame(guide, style="ModernCard.TFrame")\n            row.pack(fill="x", pady=4)\n            badge = tk.Label(row, text=number, bg="#dbeafe", fg="#1d4ed8", font=("Segoe UI", 9, "bold"), width=3, pady=3)\n            badge.pack(side="left", padx=(0, 9))\n            text = ttk.Frame(row, style="ModernCard.TFrame")\n            text.pack(side="left", fill="x", expand=True)\n            ttk.Label(text, text=title, style="GuideTitle.TLabel").pack(anchor="w")\n            ttk.Label(text, text=note, style="GuideText.TLabel", wraplength=560).pack(anchor="w")\n\n        quick = ttk.Frame(body, style="ModernCard.TFrame", padding=(18, 16))\n        quick.grid(row=0, column=1, sticky="nsew", padx=(7, 0))\n        ttk.Label(quick, text="What should I do next?", style="GuideTitle.TLabel").pack(anchor="w")\n        self.dashboard_vars["next_step"] = tk.StringVar(value="Load a bank CSV to begin.")\n        ttk.Label(quick, textvariable=self.dashboard_vars["next_step"], style="GuideText.TLabel", wraplength=360).pack(anchor="w", pady=(4, 12))\n        ttk.Button(quick, text="Load bank CSV...", command=self.load_csv, style="Accent.TButton").pack(fill="x", pady=3)\n        ttk.Button(quick, text="Review Payments", command=lambda: self._navigate_modern("payments"), style="Modern.TButton").pack(fill="x", pady=3)\n        ttk.Button(quick, text="Review Receipts", command=lambda: self._navigate_modern("receipts"), style="Modern.TButton").pack(fill="x", pady=3)\n        ttk.Button(quick, text="Check selected for errors", command=self.show_validation, style="Modern.TButton").pack(fill="x", pady=(12, 3))\n        ttk.Button(quick, text="Export selected to Pastel...", command=self.export_files, style="Accent.TButton").pack(fill="x", pady=3)\n        ttk.Separator(quick).pack(fill="x", pady=12)\n        self.dashboard_vars["statement"] = tk.StringVar(value="No statement loaded")\n        ttk.Label(quick, text="Current statement", style="CardLabel.TLabel").pack(anchor="w")\n        ttk.Label(quick, textvariable=self.dashboard_vars["statement"], style="GuideText.TLabel", wraplength=350).pack(anchor="w", pady=(2, 0))\n\n    def _refresh_dashboard(self):\n        if not hasattr(self, "dashboard_vars"):\n            return\n        payments = len(self.txns)\n        receipts = len(self.receipts)\n        selected = [t for t in (self.txns + self.receipts) if t.include]\n        ready = sum(1 for t in selected if t.account and not t.ambiguous)\n        attention = sum(1 for t in selected if (not t.account) or t.ambiguous)\n        recurring = sum(1 for t in (self.txns + self.receipts) if t.recurring_count >= 2)\n        try:\n            rules = len(self.store.all_rules())\n        except Exception:\n            rules = 0\n        for key, value in (("payments", payments), ("receipts", receipts), ("ready", ready), ("attention", attention), ("rules", rules)):\n            if key in self.dashboard_vars:\n                self.dashboard_vars[key].set(str(value))\n        if "statement" in self.dashboard_vars:\n            if self.current_file:\n                self.dashboard_vars["statement"].set(f"{Path(self.current_file).name}  |  {payments + receipts} transactions  |  {recurring} recurring")\n            else:\n                self.dashboard_vars["statement"].set("No statement loaded")\n        if "next_step" in self.dashboard_vars:\n            if not (self.txns or self.receipts):\n                text = "Start by loading a bank CSV. The app will separate Payments and Receipts automatically."\n            elif attention:\n                text = f"{attention} selected transaction(s) still need attention. Review orange/unassigned or ambiguous rows before export."\n            elif not selected:\n                text = "Nothing is selected for export. Use the additive Auto and Manual quick-select buttons on Payments / Receipts."\n            else:\n                text = f"{ready} selected transaction(s) are allocated. Run validation, then export when the checks are clear."\n            self.dashboard_vars["next_step"].set(text)\n\n    def _set_modern_page_header(self, title: str, subtitle: str):\n        self.page_title_var.set(title)\n        self.page_subtitle_var.set(subtitle)\n\n    def _set_nav_active(self, key: str):\n        for nav_key, button in getattr(self, "nav_buttons", {}).items():\n            active = nav_key == key\n            button.configure(\n                bg="#e8f0ff" if active else "#ffffff",\n                fg="#1d4ed8" if active else "#334155",\n                activebackground="#e8f0ff" if active else "#f1f5f9",\n                activeforeground="#1d4ed8" if active else "#172033",\n                font=("Segoe UI", 10, "bold" if active else "normal"),\n            )\n\n    def _show_modern_dashboard(self):\n        self.current_modern_page = "dashboard"\n        self.notebook.pack_forget()\n        self.dashboard_frame.pack(fill="both", expand=True)\n        self._set_modern_page_header("Overview", "Your statement, allocations and next steps at a glance.")\n        self._set_nav_active("dashboard")\n        self._refresh_dashboard()\n\n    def _show_modern_notebook(self, tab, key: str, title: str, subtitle: str):\n        self.current_modern_page = key\n        self.dashboard_frame.pack_forget()\n        if not self.notebook.winfo_manager():\n            self.notebook.pack(fill="both", expand=True)\n        self.notebook.select(tab)\n        self._set_modern_page_header(title, subtitle)\n        self._set_nav_active(key)\n\n    def _navigate_modern(self, key: str):\n        if self.ui_mode != "modern":\n            self.ui_mode = "modern"\n            self._apply_ui_mode("modern")\n        if key == "dashboard":\n            self._show_modern_dashboard(); return\n        pages = {\n            "payments": (self.pay_tab, "Payments", "Allocate and select money leaving the bank."),\n            "receipts": (self.receipt_tab, "Receipts", "Allocate and select money entering the bank."),\n            "recurring_payments": (self.recurring_pay_tab, "Recurring Payments", "Review repeated outgoing transactions while keeping each child transaction independently controllable."),\n            "recurring_receipts": (self.recurring_receipt_tab, "Recurring Receipts", "Review repeated incoming transactions and their individual allocations."),\n            "rules": (self.rule_tab, "Saved Rules", "Manage the rules that automate future allocations."),\n            "settings": (self.settings_tab, "Settings", "Configure VAT, fiscal periods and the Pastel cash-book bank GL for this company profile."),\n        }\n        tab, title, subtitle = pages.get(key, pages["payments"])\n        self._show_modern_notebook(tab, key, title, subtitle)\n\n    def toggle_ui_mode(self):\n        self._apply_ui_mode("classic" if self.ui_mode == "modern" else "modern")\n\n    def _apply_ui_mode(self, mode: str = None, initial: bool = False):\n        chosen = (mode or getattr(self, "ui_mode", DEFAULT_UI_MODE) or DEFAULT_UI_MODE).lower()\n        if chosen not in UI_MODES:\n            chosen = DEFAULT_UI_MODE\n        self.ui_mode = chosen\n        try:\n            self.store.set_setting("ui_mode", chosen)\n        except Exception:\n            pass\n        style = ttk.Style(self)\n        if chosen == "classic":\n            try:\n                style.theme_use("vista" if os.name == "nt" else "clam")\n            except tk.TclError:\n                pass\n            if hasattr(self, "_classic_tab_layout"):\n                try:\n                    style.layout("TNotebook.Tab", self._classic_tab_layout)\n                except tk.TclError:\n                    pass\n            self.modern_header.pack_forget()\n            self.sidebar.pack_forget()\n            self.modern_page_header.pack_forget()\n            self.dashboard_frame.pack_forget()\n            if not self.classic_toolbar.winfo_manager():\n                self.classic_toolbar.pack(fill="x", before=self.main_shell)\n            if not self.notebook.winfo_manager():\n                self.notebook.pack(fill="both", expand=True)\n            self.classic_mode_button.configure(text="Modern UI")\n            self.status_var.set("Classic UI enabled. Your data and accounting logic are unchanged.")\n        else:\n            self._configure_modern_style()\n            try:\n                style.layout("TNotebook.Tab", [])\n            except tk.TclError:\n                pass\n            self.classic_toolbar.pack_forget()\n            if not self.modern_header.winfo_manager():\n                self.modern_header.pack(fill="x", before=self.main_shell)\n            if not self.sidebar.winfo_manager():\n                self.sidebar.pack(side="left", fill="y", before=self.content_shell)\n            if not self.modern_page_header.winfo_manager():\n                self.modern_page_header.pack(fill="x")\n            self.modern_mode_button.configure(text="Classic UI")\n            page = getattr(self, "current_modern_page", "dashboard")\n            if page == "dashboard":\n                self._show_modern_dashboard()\n            else:\n                self._navigate_modern(page)\n            if not initial:\n                self.status_var.set("Modern UI enabled. Use the Overview page for guided next steps, or switch back to Classic UI at any time.")\n\n    def _restore_modern_view(self, active_tab: str, saved_page: str = ""):\n        if getattr(self, "ui_mode", DEFAULT_UI_MODE) != "modern":\n            return\n        if saved_page == "dashboard":\n            self._show_modern_dashboard(); return\n        by_tab = {\n            "Payments": "payments",\n            "Receipts / Money In": "receipts",\n            "Recurring Payments": "recurring_payments",\n            "Recurring Receipts": "recurring_receipts",\n            "Saved Rules": "rules",\n            "Settings": "settings",\n        }\n        self._navigate_modern(saved_page if saved_page in {"payments", "receipts", "recurring_payments", "recurring_receipts", "rules", "settings"} else by_tab.get(active_tab, "dashboard"))\n\n    def _build(self):\n        self.ui_mode = (self.store.get_setting("ui_mode", DEFAULT_UI_MODE) or DEFAULT_UI_MODE).strip().lower()\n        if self.ui_mode not in UI_MODES:\n            self.ui_mode = DEFAULT_UI_MODE\n        self.current_modern_page = "dashboard"\n        self.nav_buttons = {}\n\n        # Classic toolbar: deliberately keeps the previous layout available.\n        self.classic_toolbar = ttk.Frame(self, padding=(12, 10))\n        ttk.Label(self.classic_toolbar, text=APP_NAME, font=("Segoe UI", 18, "bold")).pack(side="left")\n        classic_profile_box, self.profile_combo_classic = self._build_profile_controls(self.classic_toolbar, modern=False)\n        classic_profile_box.pack(side="left", padx=(18, 8))\n        ttk.Button(self.classic_toolbar, text="Load bank CSV...", command=self.load_csv, style="Accent.TButton").pack(side="left", padx=8)\n        ttk.Button(self.classic_toolbar, text="Apply saved rules", command=self.reapply_rules).pack(side="left")\n        self.classic_mode_button = ttk.Button(self.classic_toolbar, text="Modern UI", command=self.toggle_ui_mode)\n        self.classic_mode_button.pack(side="right", padx=(4, 0))\n        ttk.Button(self.classic_toolbar, text="Check selected for errors", command=self.show_validation).pack(side="right")\n        ttk.Button(self.classic_toolbar, text="Export selected to Pastel...", command=self.export_files, style="Accent.TButton").pack(side="right", padx=8)\n\n        # Modern header: focused primary actions and a compact company switcher.\n        self.modern_header = ttk.Frame(self, style="ModernHeader.TFrame", padding=(18, 11))\n        title_box = ttk.Frame(self.modern_header, style="ModernHeader.TFrame")\n        title_box.pack(side="left")\n        ttk.Label(title_box, text=APP_NAME, style="ModernTitle.TLabel").pack(anchor="w")\n        ttk.Label(title_box, text=f"v{APP_VERSION} Personal workspace", style="ModernSubtitle.TLabel").pack(anchor="w")\n        modern_profile_box, self.profile_combo_modern = self._build_profile_controls(self.modern_header, modern=True)\n        modern_profile_box.pack(side="left", padx=(24, 0))\n        self.profile_combo = self.profile_combo_modern\n        self.modern_mode_button = ttk.Button(self.modern_header, text="Classic UI", command=self.toggle_ui_mode, style="Modern.TButton")\n        self.modern_mode_button.pack(side="right", padx=(6, 0))\n        ttk.Button(self.modern_header, text="Export to Pastel", command=self.export_files, style="Accent.TButton").pack(side="right", padx=6)\n        ttk.Button(self.modern_header, text="Validate", command=self.show_validation, style="Modern.TButton").pack(side="right", padx=4)\n        ttk.Button(self.modern_header, text="Load statement", command=self.load_csv, style="Accent.TButton").pack(side="right", padx=6)\n\n        self.main_shell = ttk.Frame(self, style="ModernPage.TFrame")\n        self.main_shell.pack(fill="both", expand=True)\n        self.sidebar = tk.Frame(self.main_shell, bg="#ffffff", width=220, highlightthickness=1, highlightbackground="#e2e8f0")\n        self.sidebar.pack_propagate(False)\n        tk.Label(self.sidebar, text="WORKSPACE", bg="#ffffff", fg="#94a3b8", font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x", padx=18, pady=(20, 8))\n        nav = [\n            ("dashboard", "Overview"),\n            ("payments", "Payments"),\n            ("receipts", "Receipts / Money In"),\n            ("recurring_payments", "Recurring Payments"),\n            ("recurring_receipts", "Recurring Receipts"),\n            ("rules", "Saved Rules"),\n            ("settings", "Settings"),\n        ]\n        for key, label in nav:\n            button = tk.Button(\n                self.sidebar, text=label, command=lambda k=key: self._navigate_modern(k), anchor="w",\n                bd=0, relief="flat", bg="#ffffff", fg="#334155", activebackground="#f1f5f9", activeforeground="#172033",\n                padx=18, pady=10, font=("Segoe UI", 10), cursor="hand2"\n            )\n            button.pack(fill="x", padx=8, pady=1)\n            self.nav_buttons[key] = button\n        tk.Frame(self.sidebar, bg="#e2e8f0", height=1).pack(fill="x", padx=16, pady=(18, 12))\n        tk.Label(self.sidebar, text="ACTIVE COMPANY", bg="#ffffff", fg="#94a3b8", font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x", padx=18)\n        tk.Label(self.sidebar, textvariable=self.profile_var, bg="#ffffff", fg="#172033", font=("Segoe UI", 10, "bold"), anchor="w", wraplength=180, justify="left").pack(fill="x", padx=18, pady=(4, 0))\n        tk.Label(self.sidebar, text="Modern and Classic views use the same company data.", bg="#ffffff", fg="#64748b", font=("Segoe UI", 8), anchor="w", wraplength=180, justify="left").pack(fill="x", padx=18, pady=(5, 0))\n\n        self.content_shell = ttk.Frame(self.main_shell, style="ModernPage.TFrame")\n        self.content_shell.pack(side="left", fill="both", expand=True)\n        self.modern_page_header = ttk.Frame(self.content_shell, style="ModernHeader.TFrame", padding=(18, 12))\n        self.page_title_var = tk.StringVar(value="Overview")\n        self.page_subtitle_var = tk.StringVar(value="Your statement, allocations and next steps at a glance.")\n        ttk.Label(self.modern_page_header, textvariable=self.page_title_var, style="ModernTitle.TLabel").pack(anchor="w")\n        ttk.Label(self.modern_page_header, textvariable=self.page_subtitle_var, style="ModernSubtitle.TLabel").pack(anchor="w", pady=(2, 0))\n\n        self.dashboard_frame = ttk.Frame(self.content_shell, style="ModernPage.TFrame")\n        self._build_dashboard()\n\n        self.notebook = ttk.Notebook(self.content_shell)\n        try:\n            self._classic_tab_layout = ttk.Style(self).layout("TNotebook.Tab")\n        except tk.TclError:\n            self._classic_tab_layout = []\n        self.pay_tab = ttk.Frame(self.notebook)\n        self.receipt_tab = ttk.Frame(self.notebook)\n        self.recurring_pay_tab = ttk.Frame(self.notebook)\n        self.recurring_receipt_tab = ttk.Frame(self.notebook)\n        self.rule_tab = ttk.Frame(self.notebook)\n        self.settings_tab = ttk.Frame(self.notebook)\n        self.notebook.add(self.pay_tab, text="Payments")\n        self.notebook.add(self.receipt_tab, text="Receipts / Money In")\n        self.notebook.add(self.recurring_pay_tab, text="Recurring Payments")\n        self.notebook.add(self.recurring_receipt_tab, text="Recurring Receipts")\n        self.notebook.add(self.rule_tab, text="Saved Rules")\n        self.notebook.add(self.settings_tab, text="Settings")\n\n        self._build_transaction_tab(self.pay_tab, "PAYMENT")\n        self._build_transaction_tab(self.receipt_tab, "RECEIPT")\n        self._build_recurring_tab(self.recurring_pay_tab, "PAYMENT")\n        self._build_recurring_tab(self.recurring_receipt_tab, "RECEIPT")\n        self._build_rules()\n        self._build_settings()\n\n        bar = ttk.Frame(self, style="StatusBar.TFrame", padding=(12, 6, 12, 8))\n        bar.pack(fill="x")\n        ttk.Label(bar, textvariable=self.status_var).pack(side="left")\n        ttk.Label(bar, textvariable=self.profile_db_var, foreground="#64748b").pack(side="right")\n\n        self._apply_ui_mode(self.ui_mode, initial=True)\n        self._refresh_dashboard()\n\n'''
    s = replace_block(
        s,
        '    def _build(self):\n',
        '    def _build_transaction_tab(self, tab, direction: str):\n',
        new_build,
        'replace legacy build shell with dual UI shell',
    )

    # Keep both profile pickers current after creating / renaming profiles.
    old_profile_refresh = '''        if hasattr(self, "profile_combo"):\n            self.profile_combo.configure(values=self.profile_manager.names())\n'''
    new_profile_refresh = '''        for _combo_name in ("profile_combo", "profile_combo_modern", "profile_combo_classic"):\n            _combo = getattr(self, _combo_name, None)\n            if _combo is not None:\n                _combo.configure(values=self.profile_manager.names())\n'''
    s = replace_once(s, old_profile_refresh, new_profile_refresh, 'refresh both profile pickers')

    # Dashboard should track normal transaction-list refreshes without changing accounting behavior.
    tree_marker = '    def _tree_click(self, event, direction: str):\n'
    s = replace_once(
        s,
        tree_marker,
        '        if hasattr(self, "dashboard_vars"):\n            self._refresh_dashboard()\n\n' + tree_marker,
        'dashboard refresh after transaction tree',
    )

    # Loading a CSV from the Overview page should reveal the selected transaction workspace.
    load_select = '        self.notebook.select(self.pay_tab if payments else self.receipt_tab)\n'
    s = replace_once(
        s,
        load_select,
        load_select + '        if getattr(self, "ui_mode", DEFAULT_UI_MODE) == "modern":\n            self._navigate_modern("payments" if payments else "receipts")\n',
        'modern view follows loaded statement',
    )

    # Remember the Modern dashboard/page alongside the existing active notebook tab.
    session_marker = '            "active_tab": active_tab,\n'
    s = replace_once(
        s,
        session_marker,
        session_marker + '            "modern_page": getattr(self, "current_modern_page", ""),\n',
        'session saves modern page',
    )

    restore_marker = '''            geometry = str(data.get("window_geometry") or "")\n'''
    s = replace_once(
        s,
        restore_marker,
        '''            saved_modern_page = str(data.get("modern_page") or "")\n            self._restore_modern_view(active_tab, saved_modern_page)\n\n''' + restore_marker,
        'session restores modern page',
    )

    # Pure self-test markers for the dual-interface contract. No display is required.
    test_marker = '    # Receipt and payment rules with the same description must never cross-apply.\n'
    tests = '''    # v1.11.21: Modern UI is the default, while Classic remains available.\n    assert DEFAULT_UI_MODE == "modern"\n    assert UI_MODES == {"modern", "classic"}\n\n'''
    s = replace_once(s, test_marker, tests + test_marker, 'dual UI self-test')

    p.write_text(s, encoding="utf-8")
    print(f"Transformed {p} to v1.11.21 with Modern dashboard UI and Classic compatibility")


if __name__ == "__main__":
    main(sys.argv[1])
